b:if.script:
//
document.documentElement.className += ' hp-home-loading';
/* 홈 내용(sl-home)을 페이지를 읽는 동안 미리 받아 둠 — [S7] 홈 로더가 이어받음
   두 번째 방문부터는 기억해 둔 페이지 번호로 바로 받음 (요청 1번) */
(function () {
  var E = window.__slEarly = { d: null, done: false, cbs: [] };
  function finish(d) { E.d = d; E.done = true; var c = E.cbs; E.cbs = []; for (var i = 0; i < c.length; i++) c[i](d); }
  function load(src) { var s = document.createElement('script'); s.src = src; s.async = true; s.onerror = function () { finish(null); }; document.head.appendChild(s); }
  var key = 'slHomeId:' + location.host, id = '';
  try { id = localStorage.getItem(key) || ''; } catch (e) {}
  window.__slEarlyPage = function (d) { finish(d && d.entry ? d : null); };
  /* 사진 보관 페이지(sl-img)가 많아도 찾도록 100개씩 넘겨 가며 찾음 (최대 1,000개) */
  var start = 1;
  function listUrl() { return '/feeds/pages/summary?max-results=100&start-index=' + start + '&alt=json-in-script&callback=__slEarlyList'; }
  window.__slEarlyList = function (d) {
    var list = (d && d.feed && d.feed.entry) || [];
    for (var i = 0; i < list.length; i++) {
      var m = list[i].title && list[i].title.$t === 'sl-home' && String(list[i].id && list[i].id.$t).match(/page-(\d+)/);
      if (m) { try { localStorage.setItem(key, m[1]); } catch (e) {} load('/feeds/pages/default/' + m[1] + '?alt=json-in-script&callback=__slEarlyPage'); return; }
    }
    if (list.length === 100 && start < 901) { start += 100; load(listUrl()); return; }
    finish(null);
  };
  load(id ? '/feeds/pages/default/' + id + '?alt=json-in-script&callback=__slEarlyPage' : listUrl());
})();
//

//
(function () {
  var c = null, show = true;
  try {
    if (sessionStorage.getItem('slSplashSeen')) show = false;
    c = JSON.parse(localStorage.getItem('slSplash:' + location.host) || 'null');
    if (c && c.on === 0) show = false;
    if (show) sessionStorage.setItem('slSplashSeen', '1');
  } catch (e) {}
  if (/[?&]sladmin=/.test(location.search)) show = false;
  if (!show) return;
  document.documentElement.className += ' sl-splash-on';
  window.__slSplash = { t0: Date.now(), c: c || {} };
  if (c && c.bg) { var l = document.createElement('link'); l.rel = 'preload'; l.as = 'image'; l.href = c.bg; document.head.appendChild(l); }
})();
//

head.b:template-skin:
/* ══════════════════════════════════════════════════════
   [A] body 기본
   ══════════════════════════════════════════════════════ */
body#layout {
  overflow: visible !important;
  background: #f1f5f9 !important;
  min-height: 100vh !important;
  font: normal normal 13px 'Noto Sans KR', sans-serif !important;
}

/* ══════════════════════════════════════════════════════
   [B] box-sizing 전체 적용
   ══════════════════════════════════════════════════════ */
body#layout *,
body#layout *::before,
body#layout *::after {
  box-sizing: border-box !important;
}

/* ══════════════════════════════════════════════════════
   [C] overflow / float / clear 통합 리셋
   ══════════════════════════════════════════════════════ */
body#layout,
body#layout #outer-wrapper,
body#layout #main-wrapper,
body#layout #content-wrapper,
body#layout #left-section,
body#layout #right-section,
body#layout .blog-posts,
body#layout .section,
body#layout .widget-content,
body#layout .blog-widget,
body#layout .HTML,
body#layout .LinkList,
body#layout .PopularPosts,
body#layout .RecentPosts,
body#layout .Label,
body#layout #sidebar-wrapper,
body#layout #right-sidebar,
body#layout .sidebar-container,
body#layout .post-outer,
body#layout .blog-pager,
body#layout #comments,
body#layout #post-top-ad-zone,
body#layout #post-middle-ad-zone,
body#layout #post-bottom-ad-zone,
body#layout #below-nav-ad-zone,
body#layout #ad-target-below-title,
body#layout #ad-target-below-post,
body#layout #ad-target-below-nextprev,
body#layout #ad-middle-source,
body#layout #Post-Middle-Ad-Zone,
body#layout .inline-ad {
  overflow: visible !important;
  float: none !important;
  clear: none !important;
}

/* ══════════════════════════════════════════════════════
   [C-1] 레이아웃 편집기 전용 — 화면용 요소 숨김
         (본문 바로가기 / 슬라이드 메뉴 / 저작권 줄)
   ══════════════════════════════════════════════════════ */
body#layout .skip-link,
body#layout #slide-menu,
body#layout #slide-menu-overlay,
body#layout .footer-copy,
body#layout .header-title,
body#layout #slide-menu-trigger { display: none !important; }

/* ══════════════════════════════════════════════════════
   [D] 캔버스 1열 정렬 — 모든 영역을 같은 너비(600px)로 중앙 정렬
       바깥 래퍼는 투명 처리하고, 섹션 상자만 보이게 함
   ══════════════════════════════════════════════════════ */
body#layout #global-header,
body#layout .header-inner,
body#layout .header-menu-pc,
body#layout #outer-wrapper,
body#layout #left-section,
body#layout #right-section,
body#layout .ad-warehouse,
body#layout .ad-warehouse-nav,
body#layout #site-footer,
body#layout .footer-inner,
body#layout .hp-config {
  display: block !important;
  position: static !important;
  float: none !important;
  width: 100% !important;
  max-width: 600px !important;
  min-width: 0 !important;
  height: auto !important;
  margin: 0 auto !important;
  padding: 0 !important;
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
}
body#layout #global-header { margin-top: 20px !important; }
body#layout #site-footer { margin-top: 0 !important; }

/* ══════════════════════════════════════════════════════
   [E] 섹션 상자 — 너비 동일 / 상자 사이 16px 간격
   ══════════════════════════════════════════════════════ */
body#layout .section,
body#layout #Post-Middle-Ad-Zone,
body#layout section#Post-Middle-Ad-Zone,
body#layout div#Post-Middle-Ad-Zone {
  display: block !important;
  width: 100% !important;
  max-width: 600px !important;
  min-width: 0 !important;
  min-height: 50px !important;
  height: auto !important;
  margin: 0 auto 16px auto !important;
  padding: 14px 16px 10px !important;
  border: 1px dashed #cbd5e1 !important;
  background-color: #f8fafc !important;
  border-radius: 8px !important;
  overflow: visible !important;
  box-sizing: border-box !important;
}

/* 섹션 이름(h4) 아래 여백 */
body#layout .section > h4,
body#layout .section h4 {
  margin: 0 0 12px !important;
  font-size: 13px !important;
  font-weight: 700 !important;
}

/* ══════════════════════════════════════════════════════
   [F] 가젯 추가 버튼 — 가젯 상자와 10px 띄움
   ══════════════════════════════════════════════════════ */
body#layout .add_widget,
body#layout .add-widget,
body#layout a.add-widget,
body#layout .add-gadget,
body#layout a.add-gadget {
  display: block !important;
  position: relative !important;
  float: none !important;
  left: auto !important;
  right: auto !important;
  /* width:auto — 섹션 안쪽 폭에 자동으로 맞춤 (Blogger 기본 폭·여백이 섹션 밖으로 밀어내는 문제 차단) */
  width: auto !important;
  min-width: 0 !important;
  max-width: none !important;
  margin: 0 0 12px 0 !important;
  box-sizing: border-box !important;
  border-radius: 6px !important;
}

/* ══════════════════════════════════════════════════════
   [G] 가젯(위젯) 상자 — 섹션 안에서 꽉 차게 / 상자 사이 10px
   ══════════════════════════════════════════════════════ */
body#layout div.widget,
body#layout div.widget[id] {
  display: block !important;
  width: 100% !important;
  max-width: 100% !important;
  min-width: 0 !important;
  box-sizing: border-box !important;
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
  border-radius: 6px !important;
  padding: 0 !important;
  margin: 0 0 10px 0 !important;
  opacity: 1 !important;
  overflow: visible !important;
  position: relative !important;
  float: none !important;
}
body#layout .draggable-widget,
body#layout .locked-widget .widget-content {
  border-radius: 6px !important;
  overflow: hidden !important;
}

/* 위젯 내부 콘텐츠 */
body#layout .widget-content {
  padding-left: 0 !important;
  padding-right: 0 !important;
  width: 100% !important;
  max-width: 100% !important;
}

/* ══════════════════════════════════════════════════════
   [H] 컨테이너 리셋
   ══════════════════════════════════════════════════════ */
body#layout #post-top-ad-zone,
body#layout #post-middle-ad-zone,
body#layout #post-bottom-ad-zone,
body#layout #below-nav-ad-zone,
body#layout #ad-target-below-title,
body#layout #ad-target-below-post,
body#layout #ad-target-below-nextprev,
body#layout #ad-middle-source,
body#layout .inline-ad,
body#layout .post-outer,
body#layout .blog-pager,
body#layout #comments {
  width: 100% !important;
  max-width: 100% !important;
  min-width: 0 !important;
  padding: 8px !important;
  margin: 4px 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  border-radius: 0 !important;
}

body#layout .post-body img,
body#layout .post-body .separator a img {
  width: auto !important;
  max-width: 100% !important;
  margin: 0 !important;
  height: auto !important;
}

/* ══════════════════════════════════════════════════════
   [I] 표시 스위치(눈 아이콘) 색상
       ON(표시) → 파랑 #2563eb / OFF(숨김) → 빨강 #dc2626
       ※ 연필(수정) 아이콘은 색 변경 대상에서 제외
   ══════════════════════════════════════════════════════ */
body#layout div.widget [class*="visib"],
body#layout div.widget [class*="visib"] *,
body#layout div.widget [aria-label*="숨기"],
body#layout div.widget [aria-label*="숨기"] *,
body#layout div.widget [title*="숨기"],
body#layout div.widget [title*="숨기"] *,
body#layout div.widget [aria-label*="Hide"],
body#layout div.widget [aria-label*="Hide"] *,
body#layout div.widget [data-tooltip*="숨기"],
body#layout div.widget [data-tooltip*="숨기"] * {
  color: #2563eb !important;
  fill: #2563eb !important;
  opacity: 1 !important;
}

body#layout div.widget.invisible [class*="visib"],
body#layout div.widget.invisible [class*="visib"] *,
body#layout div.widget [class*="visibility-off"],
body#layout div.widget [class*="visibility-off"] *,
body#layout div.widget [class*="visib"][aria-pressed="false"],
body#layout div.widget [class*="visib"][aria-pressed="false"] *,
body#layout div.widget [aria-label*="표시"],
body#layout div.widget [aria-label*="표시"] *,
body#layout div.widget [title*="표시"],
body#layout div.widget [title*="표시"] *,
body#layout div.widget [aria-label*="Show"],
body#layout div.widget [aria-label*="Show"] *,
body#layout div.widget [data-tooltip*="표시"],
body#layout div.widget [data-tooltip*="표시"] * {
  color: #dc2626 !important;
  fill: #dc2626 !important;
  opacity: 1 !important;
}

/* 숨김 가젯 이름 — 빨강 취소선 */
body#layout div.widget.invisible .layout-title,
body#layout div.widget.invisible .layout-widget-description {
  color: #991b1b !important;
  text-decoration: line-through !important;
}

/* ══════════════════════════════════════════════════════
   [J] ul/li 리셋
   ══════════════════════════════════════════════════════ */
body#layout .widget-content ul,
body#layout .widget-content ol {
  list-style: none !important;
  padding: 0 !important;
  margin: 0 !important;
}
body#layout .widget-content li {
  padding: 4px 0 !important;
  border-bottom: none !important;
  font-size: 12px !important;
  color: #555 !important;
  line-height: 1.4 !important;
  white-space: normal !important;
}

/* ══════════════════════════════════════════════════════
   [K] 안내(가이드) 섹션 — 색상 구분, 너비는 다른 섹션과 동일
   ══════════════════════════════════════════════════════ */
body#layout #Homepage-WebApp-Section {
  border: 2px dashed #3b82f6 !important;
  background: #eff6ff !important;
  padding: 16px !important;
}
body#layout #Homepage-WebApp-Section::before {
  content: "헤더 메뉴 영역 (헤더 활성화 위젯으로 페이지별 표시)";
  display: block;
  font-weight: bold;
  color: #2563eb;
  margin-bottom: 12px;
  font-size: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid #bfdbfe;
}

body#layout #Homepage-Content-Section {
  border: 2px dashed #10b981 !important;
  background: #ecfdf5 !important;
  padding: 16px !important;
}
body#layout #Homepage-Content-Section::before {
  content: "메인화면 콘텐츠 영역 (홈에서만 표시)";
  display: block;
  font-weight: bold;
  color: #059669;
  margin-bottom: 12px;
  font-size: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid #6ee7b7;
}

body#layout #Global-Config-Section,
body#layout #Home-Config-Section {
  border: 2px dashed #a855f7 !important;
  background: #faf5ff !important;
  padding: 16px !important;
}
body#layout #Global-Config-Section::before,
body#layout #Home-Config-Section::before {
  display: block;
  font-weight: bold;
  color: #7e22ce;
  margin-bottom: 12px;
  font-size: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid #e9d5ff;
}
body#layout #Global-Config-Section::before { content: "설정 가젯 — 전체 페이지 공통 (화면에 안 보임)"; }
body#layout #Home-Config-Section::before { content: "설정 가젯 — GAS 연동 · AI (홈에서만, 화면에 안 보임)"; }

head.script:
