b:if.script:
//
/* 로딩 화면: 지난 방문에 기억해 둔 대표 사진·로고·상호·문구로 채우고, 홈이 그려지면 걷음 (최소 1.2초 · 최대 3초 · 누르면 바로) */
(function () {
  var S = window.__slSplash, el = document.getElementById('sl-splash');
  if (!S || !el) return;
  var c = S.c || {}, q = function (k) { return el.querySelector(k); };
  if (c.name) q('.sp-name').textContent = c.name;
  if (c.line) q('.sp-line').textContent = c.line;
  if (c.logo) { var lg = q('.sp-logo'); lg.src = c.logo; lg.hidden = false; }
  if (c.bg) el.style.backgroundImage = 'url("' + String(c.bg).replace(/"/g, '') + '")';
  else if (/^#[0-9a-f]{3,6}$/i.test(c.color || '')) el.style.background = 'linear-gradient(140deg,' + c.color + ',#111418)';
  var gone = false;
  function close(now) {
    if (gone) return;
    var wait = now ? 0 : Math.max(0, 1200 - (Date.now() - S.t0));
    gone = true;
    setTimeout(function () {
      document.documentElement.classList.add('sl-splash-out');
      setTimeout(function () { if (el.parentNode) el.parentNode.removeChild(el); document.documentElement.classList.remove('sl-splash-on', 'sl-splash-out'); }, 500);
    }, wait);
  }
  el.addEventListener('click', function () { gone = false; close(true); });
  document.addEventListener('sl:home', function () { close(false); });
  setTimeout(function () { gone = false; close(true); }, 3000);
})();
//

//
(function () {
  /* 라벨 '검색제외' 를 단 글 — 검색엔진이 색인하지 않도록 로봇 태그를 바꿈 */
  var m = document.querySelector('meta[name="robots"]');
  if (!m) { m = document.createElement('meta'); m.name = 'robots'; document.head.appendChild(m); }
  m.content = 'noindex, follow';
})();
//
